"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6328],{46328:a=>{a.exports=JSON.parse('{"slug":"samolet-tekhdefolt-reyting-gendirektor","locale":"es","title":"Samolet retrasa un bono, recibe 2 rebajas de calificaci\xf3n y pierde a su directora general en un mes","description":"Samolet incurre en impago t\xe9cnico; 2 agencias bajan su nota a BBB y su directora sale tras las sanciones europeas. Qu\xe9 implica para compradores e inversores.","blocks":[{"id":"b001","kind":"paragraph","text":"A finales de septiembre de 2026, Samolet retras\xf3 un d\xeda la amortizaci\xf3n de bonos por 2,5 mil millones de rublos, atribuy\xe9ndolo a una demora en la transferencia. Es un impago t\xe9cnico: afirma tener el dinero, pero no lleg\xf3 a tiempo. ACRA rebaj\xf3 despu\xe9s la nota a BBB con perspectiva negativa; el 15 de octubre, NCR hizo lo mismo desde A."},{"id":"b002","kind":"paragraph","text":"La nota crediticia expresa la probabilidad de devolver la deuda. Como el historial de una persona: cuanto peor, mayor inter\xe9s en el siguiente pr\xe9stamo. NCR se\xf1ala m\xe1s endeudamiento, menor capacidad de servicio y rentabilidad debilitada. Vincula la perspectiva negativa al endurecimiento hipotecario: con hipotecas m\xe1s caras se venden menos pisos y cuesta m\xe1s pagar la deuda."},{"id":"b003","kind":"paragraph","text":"A mediados de octubre, la UE sancion\xf3 a Samolet y a Anna Akinshina por trabajadores norcoreanos en obras de Vladivostok, que considera contrarios a las sanciones de la ONU de 2017. El 16 de octubre, la empresa anunci\xf3 su salida por motivos personales y propuso a Ivan Ivanov, responsable de Samolet Select. Otros 2 consejeros dimitieron sin que se publicaran sus nombres."},{"id":"b004","kind":"paragraph","text":"Sberbank es el principal acreedor, con 274,2 mil millones de rublos de exposici\xf3n. Alexander Vedyakhin afirma que trabaja con todos los acreedores en un plan de mejora. El 9 de octubre, Construcci\xf3n reuni\xf3 a promotoras, bancos y Hacienda y exigi\xf3 movilizar recursos para que una gran promotora terminara todas las viviendas. El comunicado no identific\xf3 la empresa."},{"id":"b005","kind":"paragraph","text":"Los problemas vienen de antes. A principios de 2026, Samolet pidi\xf3 un pr\xe9stamo bonificado de 48–50 mil millones, pero una subcomisi\xf3n de Finanzas no vio dificultades cr\xedticas. Las acciones salieron a bolsa a 950 rublos; en julio bajaron de 300 tras renunciar al dividendo y el 16 de octubre rondaban 247,6, casi 4 veces menos. No es un caso aislado: Expert RA se\xf1ala que las rebajas fueron el 8,1% de sus actuaciones sobre empresas productivas de alta nota durante 9 meses de 2026, frente al 1,8% de todo 2025."},{"id":"b006","kind":"paragraph","text":"El comprador quiere saber si terminar\xe1n su vivienda. El ministerio lo exige y el principal banco prepara un plan, por lo que ambos apoyan la finalizaci\xf3n. Para el bonista, la rebaja significa m\xe1s riesgo y mayor inter\xe9s exigido. Mantener los t\xedtulos apuesta por el plan de Sberbank; vender ahora fija una p\xe9rdida al precio reducido. No se conoce el plan ni si llegar\xe1 antes de los pr\xf3ximos pagos."},{"id":"b007","kind":"heading","text":"\xbfQu\xe9 pas\xf3 con Samolet?"},{"id":"b008","kind":"paragraph","text":"A finales de septiembre de 2026 retras\xf3 un d\xeda bonos por 2,5 mil millones. ACRA y NCR bajaron la nota a BBB con perspectiva negativa; la UE sancion\xf3 a la empresa y a su directora, Anna Akinshina, que anunci\xf3 su salida."},{"id":"b009","kind":"heading","text":"\xbfQu\xe9 es un impago t\xe9cnico?"},{"id":"b010","kind":"paragraph","text":"Una demora de varios d\xedas cuando hay dinero, pero el pago no llega a tiempo. Samolet se retras\xf3 un d\xeda y lo atribuy\xf3 a la transferencia. El mercado lo interpreta igualmente como se\xf1al de liquidez ajustada."},{"id":"b011","kind":"heading","text":"\xbfQu\xe9 pasar\xe1 con sus viviendas?"},{"id":"b012","kind":"paragraph","text":"El 9 de octubre, Construcci\xf3n exigi\xf3 recursos bancarios para terminar las obras y cumplir con los compradores. Sberbank, principal acreedor de Samolet, prepara un plan a\xfan no anunciado."}],"sources":[{"label":"Impagos del mercado ruso de deuda del 12 al 16 de octubre","url":"https://frankmedia.ru/310263"},{"label":"Samolet anuncia un cambio de direcci\xf3n general","url":"https://frankmedia.ru/310548"},{"label":"NCR rebaja Samolet a BBB tras ACRA","url":"https://frankmedia.ru/310395"},{"label":"Una promotora rusa sancionada cambia de directora","url":"https://lenta.ru/news/2026/10/16/popavvshiy-pod-sanktsii-rossiyskiy-zastroyschik-ob-yavil-o-smene-gendirektora"},{"label":"Las autoridades exigen apoyo bancario a las promotoras","url":"https://lenta.ru/news/2026/10/09/mobilizovat"}],"sourceBodySha256":"556c692bc853437d88a15a7dc68acf4d7948a9d61dd5f274aba150be3640471e"}')}}]);